const ExcelJS = require("exceljs");

const HEADERS = [
  "Test Case ID", "Module/Section", "Test Scenario", "Priority",
  "Test Steps", "Test Data", "Expected Result", "Actual Result",
  "Pass/Fail", "Comments/Issues", "Tester Name", "Test Date",
];

const COL_WIDTHS = [15, 22, 38, 10, 55, 32, 44, 44, 12, 32, 16, 14];

const HEADER_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FF1F4E78" } };
const HEADER_FONT = { name: "Arial", size: 11, bold: true, color: { argb: "FFFFFFFF" } };
const GRAY_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FFF2F2F2" } };
const WHITE_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FFFFFFFF" } };
const DATA_FONT = { name: "Arial", size: 10 };
const THIN_BORDER = {
  top: { style: "thin", color: { argb: "FFD3D3D3" } },
  bottom: { style: "thin", color: { argb: "FFD3D3D3" } },
  left: { style: "thin", color: { argb: "FFD3D3D3" } },
  right: { style: "thin", color: { argb: "FFD3D3D3" } },
};
const MEDIUM_BORDER = {
  top: { style: "medium", color: { argb: "FF1F4E78" } },
  bottom: { style: "medium", color: { argb: "FF1F4E78" } },
  left: { style: "medium", color: { argb: "FF1F4E78" } },
  right: { style: "medium", color: { argb: "FF1F4E78" } },
};

const GREEN_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FFC6EFCE" } };
const RED_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FFFFC7CE" } };
const YELLOW_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FFFFEB9C" } };

function addSheet(wb, sheetName, rows, prefix) {
  const ws = wb.addWorksheet(sheetName);
  ws.columns = HEADERS.map((h, i) => ({ header: h, key: `col${i}`, width: COL_WIDTHS[i] }));

  const headerRow = ws.getRow(1);
  headerRow.eachCell((cell) => {
    cell.fill = HEADER_FILL;
    cell.font = HEADER_FONT;
    cell.border = MEDIUM_BORDER;
    cell.alignment = { horizontal: "center", vertical: "middle", wrapText: true };
  });
  headerRow.height = 30;

  rows.forEach((r, i) => {
    const row = ws.addRow([
      `${prefix}-${String(i + 1).padStart(3, "0")}`,
      r.section, r.scenario, r.priority,
      r.steps, r.testData, r.expected,
      "", "Not Tested", "", "", "",
    ]);
    const isGray = i % 2 === 1;
    row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
      cell.font = DATA_FONT;
      cell.border = THIN_BORDER;
      cell.fill = isGray ? GRAY_FILL : WHITE_FILL;
      const wrapCols = [5, 6, 7, 8, 10];
      cell.alignment = {
        vertical: "top",
        wrapText: wrapCols.includes(colNumber),
        horizontal: colNumber === 4 ? "center" : (colNumber === 9 ? "center" : "left"),
      };
    });
    row.height = 45;
  });

  ws.views = [{ state: "frozen", ySplit: 1 }];
  ws.autoFilter = { from: "A1", to: `L${rows.length + 1}` };

  const priorityCol = 4;
  const passFailCol = 9;
  for (let r = 2; r <= rows.length + 1; r++) {
    ws.getCell(r, priorityCol).dataValidation = {
      type: "list", allowBlank: true, formulae: ['"High,Medium,Low"'],
    };
    ws.getCell(r, passFailCol).dataValidation = {
      type: "list", allowBlank: true, formulae: ['"Pass,Fail,Blocked,Not Tested"'],
    };
  }

  ws.addConditionalFormatting({
    ref: `I2:I${rows.length + 1}`,
    rules: [
      { type: "cellIs", operator: "equal", formulae: ['"Pass"'], style: { fill: GREEN_FILL }, priority: 1 },
      { type: "cellIs", operator: "equal", formulae: ['"Fail"'], style: { fill: RED_FILL }, priority: 2 },
      { type: "cellIs", operator: "equal", formulae: ['"Blocked"'], style: { fill: YELLOW_FILL }, priority: 3 },
      { type: "cellIs", operator: "equal", formulae: ['"Not Tested"'], style: { fill: YELLOW_FILL }, priority: 4 },
    ],
  });

  return rows.length;
}

