// ═══════════════════════════════════════════════
// MAIN: Build and save Excel workbook
// ═══════════════════════════════════════════════
async function main() {
  const wb = new ExcelJS.Workbook();
  wb.creator = "SAIL PMS UAT";
  wb.created = new Date();
  wb.modified = new Date();

  const sheets = [
    { name: "Components Module", fn: getComponentsTestCases, prefix: "COMP" },
    { name: "Work Orders Module", fn: getWorkOrdersTestCases, prefix: "WO" },
    { name: "Running Hours Module", fn: getRunningHoursTestCases, prefix: "RH" },
    { name: "Spares Module", fn: getSparesTestCases, prefix: "SPARE" },
    { name: "Stores Module", fn: getStoresTestCases, prefix: "STORE" },
    { name: "Reports Module", fn: getReportsTestCases, prefix: "RPT" },
    { name: "Dashboard & Admin", fn: getDashboardAdminTestCases, prefix: "DA" },
  ];

  let totalCases = 0;
  sheets.forEach(({ name, fn, prefix }) => {
    const cases = fn();
    totalCases += cases.length;
    addSheet(wb, name, cases, prefix);
    console.log(`Sheet "${name}": ${cases.length} test cases`);
  });

  console.log(`\nTotal test cases: ${totalCases}`);

  const outPath = "PMS_UAT_TestCases_Comprehensive.xlsx";
  await wb.xlsx.writeFile(outPath);
  console.log(`Saved: ${outPath}`);
}

main().catch(console.error);
